// Turns yesterday's Twilio message log into one short text for the owner.
const s = $('Your settings').first().json;
const biz = String(s.business_number || '').trim();
const owner = String(s.owner_cell || '').trim();
const tz = s.timezone || 'America/New_York';
const hours = Number(s.lookback_hours) > 0 ? Number(s.lookback_hours) : 24;
const maxList = Number(s.max_waiting_listed) > 0 ? Number(s.max_waiting_listed) : 5;
const now = DateTime.now().setZone(tz);
const since = now.minus({ hours });

const all = [
  ...($('Texts to your number').first().json.messages || []),
  ...($('Texts from your number').first().json.messages || []),
];
// Twilio can return the same message in both lists if you text yourself. De-duplicate by sid.
const seen = new Set();
const msgs = all.filter(m => m && m.sid && !seen.has(m.sid) && seen.add(m.sid))
  .map(m => ({ ...m, at: DateTime.fromRFC2822(m.date_sent || m.date_created || '', { zone: 'utc' }) }))
  .filter(m => m.at.isValid);

const isIn = m => String(m.direction || '').startsWith('inbound');
const other = m => isIn(m) ? m.from : m.to;
const inWindow = msgs.filter(m => m.at >= since);

// Customer traffic only: your own cell texting the business number is left out.
const inbound = inWindow.filter(m => isIn(m) && m.from !== owner && m.from !== biz);
const outbound = inWindow.filter(m => !isIn(m) && m.to !== owner);
const people = new Set(inbound.map(m => m.from));
const failed = outbound.filter(m => ['failed', 'undelivered'].includes(m.status));

// Waiting on you: the last message in the conversation came from the customer.
// Looked at across everything fetched, not only the window, so an old unanswered text still shows.
const last = new Map();
for (const m of msgs) {
  const n = other(m);
  if (!n || n === owner || n === biz) continue;
  if (!last.has(n) || m.at > last.get(n).at) last.set(n, m);
}
const pretty = n => String(n).replace(/^\+1(\d{3})(\d{3})(\d{4})$/, '($1) $2-$3');
const waiting = [...last.values()]
  .filter(m => isIn(m) && !/^\s*(stop|unsubscribe|cancel|end|quit)\s*$/i.test(m.body || ''))
  .sort((a, b) => b.at - a.at);

const lines = [];
if (inbound.length) lines.push(inbound.length + ' texts in from ' + people.size + (people.size === 1 ? ' number' : ' numbers') + '.');
if (outbound.length) lines.push(outbound.length + ' sent.');
if (failed.length) lines.push(failed.length + ' did not deliver, worth a look in Twilio.');
if (waiting.length) {
  const shown = waiting.slice(0, maxList).map(m => pretty(m.from) + ' (' + m.at.setZone(tz).toFormat('ccc h:mm a') + ')');
  lines.push('Waiting on you, newest first: ' + shown.join(', ') + (waiting.length > maxList ? ', plus ' + (waiting.length - maxList) + ' more.' : '.'));
}

// Quiet means no customer traffic. Texts between your own cell and the business number do not count.
const quiet = inbound.length === 0 && outbound.length === 0;
const greeting = 'Morning. Last ' + hours + ' hours on ' + pretty(biz) + ': ';
const text = quiet
  ? greeting + 'quiet, nothing came in or went out.' + (waiting.length ? ' Still waiting on you: ' + waiting.slice(0, maxList).map(m => pretty(m.from)).join(', ') + '.' : '')
  : greeting + lines.join(' ');

return [{ json: { text, quiet, waiting: waiting.length, inbound: inbound.length, outbound: outbound.length, failed: failed.length, owner, biz } }];
